import FWCore.ParameterSet.Config as cms
from FWCore.ParameterSet.VarParsing import VarParsing

# End-to-end test of the ONNX Runtime soft jet tagger:
#   SoftJetTestData builds synthetic jets (5 jets in 3 BX crossings, one empty),
#   SoftJetTagONNX transforms them and runs the ONNX ParticleTransformer on them
#   (one jet per batch, as required by the hardcoded reshape in the exported
#   model; see SoftJetIdONNX), and SoftJetCheck compares the b-jet scores with
#   the reference values below.
# The reference values and the synthetic event are generated by
# generateSoftJetONNXTest.py, which scores the same inputs with the Python
# ONNX Runtime; re-run it when the model or the event change.

options = VarParsing("analysis")
options.register("backend", "serial_sync",
                 VarParsing.multiplicity.singleton, VarParsing.varType.string,
                 "alpaka backend: serial_sync | cuda_async | rocm_async")
options.register("model", "L1TriggerScouting/JetTagging/data/btagging/softjet_part_example.onnx",
                 VarParsing.multiplicity.singleton, VarParsing.varType.string,
                 "ONNX model")
options.parseArguments()

process = cms.Process("SoftJetTaggingONNXTest")
process.load("FWCore.MessageService.MessageLogger_cfi")
process.load("Configuration.StandardSequences.Accelerators_cff")
process.MessageLogger.cerr.FwkReport.reportEvery = 1
process.options.numberOfStreams = 2
process.options.numberOfThreads = 2

process.maxEvents.input = 2
process.source = cms.Source("EmptySource")

# the ONNX Runtime environment and execution providers
process.ONNXService = cms.Service("ONNXService")

alpaka = cms.untracked.PSet(backend=cms.untracked.string(options.backend))

from L1TriggerScouting.JetTagging.modules import (
    l1sc_SoftJetONNXTestSource_alpaka,
    l1sc_SoftJetIdONNX_alpaka,
    l1sc_SoftJetONNXTestSink_alpaka,
)

# --- begin generated block (generateSoftJetONNXTest.py) ---
pt = [45.0, 12.0, 3.5, 1.8, 0.9, 23.354, 13.503, 25.843, 21.103, 3.369, 29.283, 22.978, 23.71, 4.367, 13.841, 11.501, 27.847, 19.53, 24.789, 13.636, 7.281, 16.905, 2.476, 24.932, 19.171, 9.0, 4.0, 2.2, 1.1, 25.0, 18.0, 6.5, 3.0, 2.0, 1.5, 1.0, 0.7, 33.0]
eta = [0.11, 0.35, 1.9, -0.44, 2.2, 1.239, -0.698, 2.259, 1.887, 1.336, -1.466, -0.16, -2.19, -1.659, 0.879, 1.175, 2.244, -0.836, -0.622, -0.146, -1.491, -1.776, -0.117, -1.311, 0.815, -1.5, -1.2, -1.8, -0.9, 0.3, 0.1, 0.55, -0.2, 0.8, -0.6, 1.1, 0.0, 0.9]
phi = [0.05, 1.2, -0.6, 2.5, -1.7, -0.377, 1.996, 1.202, -1.126, 1.994, 1.829, -0.675, -1.27, 1.095, -2.161, -1.801, -2.956, 1.722, 0.989, 1.231, 1.684, -0.247, 0.412, -2.161, -2.313, 2.8, 2.5, -2.9, 3.1, -0.2, 0.15, -0.45, 0.7, -0.9, 1.3, -1.5, 0.05, 1.1]
z0 = [0.1, 0.12, 0.35, -0.2, 0.05, 0.168, -0.029, 0.065, 0.265, 0.135, 0.054, 0.059, -0.196, -0.469, -0.063, -0.285, -0.091, 0.353, -0.266, -0.442, -0.219, -0.206, 0.162, 0.057, 0.284, 0.02, 0.08, -0.1, 0.15, -0.4, -0.38, -0.3, -0.5, -0.2, -0.45, 0.1, -0.42, -0.35]
dxy = [0.001, 0.01, 0.05, 0.2, 0.002, 0.199, 0.122, 0.244, 0.05, 0.007, 0.027, 0.217, 0.139, 0.048, 0.15, 0.046, 0.209, 0.134, 0.114, 0.09, 0.189, 0.109, 0.026, 0.035, 0.289, 0.005, 0.02, 0.1, 0.05, 0.002, 0.004, 0.03, 0.15, 0.01, 0.06, 0.25, 0.001, 0.01]
puppiw = [0.99, 0.85, 0.5, 0.3, 0.9, 0.918, 0.73, 0.339, 0.972, 0.801, 0.745, 0.504, 0.345, 0.187, 0.912, 0.51, 0.282, 0.375, 0.621, 0.259, 0.871, 0.783, 0.748, 0.489, 0.665, 0.95, 0.8, 0.6, 0.7, 1.0, 0.9, 0.7, 0.4, 0.85, 0.55, 0.2, 0.95, 0.98]
pdgid = [211, -211, 130, 22, 211, -211, -13, 211, -13, -13, 211, 2112, 22, 321, 211, -211, 11, -211, 130, -13, -211, 2112, 211, -211, -13, 211, 22, 130, -211, -13, 211, -211, 130, 22, 211, -211, 22, 211]
jetOffsets = [0, 5, 25, 29, 37, 38]
jetBxOffsets = [0, 3, 5, 5]
vertexZ0 = [0.15000000596046448, -0.4000000059604645]
vertexBxOffsets = [0, 1, 2, 2]
expectedScores = [0.99401927, 0.921503127, 0.891509831, 0.995062649, 0.142375886]
# --- end generated block ---

process.SoftJetTestData = l1sc_SoftJetONNXTestSource_alpaka(
    alpaka=alpaka,
    pt=cms.vdouble(*pt),
    eta=cms.vdouble(*eta),
    phi=cms.vdouble(*phi),
    z0=cms.vdouble(*z0),
    dxy=cms.vdouble(*dxy),
    puppiw=cms.vdouble(*puppiw),
    pdgid=cms.vint32(*pdgid),
    jetOffsets=cms.vuint32(*jetOffsets),
    jetBxOffsets=cms.vuint32(*jetBxOffsets),
    vertexZ0=cms.vdouble(*vertexZ0),
    vertexBxOffsets=cms.vuint32(*vertexBxOffsets),
)

process.SoftJetTagONNX = l1sc_SoftJetIdONNX_alpaka(
    alpaka=alpaka,
    model=cms.FileInPath(options.model),
    pf=cms.InputTag("SoftJetTestData"),
    clusters=cms.InputTag("SoftJetTestData"),
    jetBxLookup=cms.InputTag("SoftJetTestData:jetBxLookup"),
    vertices=cms.InputTag("SoftJetTestData"),
    vertexBxLookup=cms.InputTag("SoftJetTestData:vertexBxLookup"),
)

process.SoftJetCheck = l1sc_SoftJetONNXTestSink_alpaka(
    alpaka=alpaka,
    src=cms.InputTag("SoftJetTagONNX"),
    expectedScores=cms.vdouble(*expectedScores),
    tolerance=cms.double(1e-4),
)

process.path = cms.Path(
    process.SoftJetTestData +
    process.SoftJetTagONNX +
    process.SoftJetCheck
)
